import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"Audit logging","description":"","frontmatter":{},"headers":[],"relativePath":"audit.md","filePath":"audit.md"}'),r={name:"audit.md"};function n(s,e,d,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="audit-logging" tabindex="-1">Audit logging <a class="header-anchor" href="#audit-logging" aria-label="Permalink to &quot;Audit logging&quot;">​</a></h1><p>Every MCP tool call produces an audit event, including calls that fail before any work happens.</p><h2 id="what-is-recorded" tabindex="-1">What is recorded <a class="header-anchor" href="#what-is-recorded" aria-label="Permalink to &quot;What is recorded&quot;">​</a></h2><p>Each audit event records:</p><ul><li>the correlation ID,</li><li>the AI credential ID and agent identity,</li><li>the tool name,</li><li>the action,</li><li>the permission used,</li><li>the target,</li><li>a sanitized input summary,</li><li>a result summary,</li><li>the outcome,</li><li>an error category,</li><li>the duration in milliseconds.</li></ul><p>Administrator-initiated credential and approval changes are audited with the administrator&#39;s user ID.</p><h2 id="outcome-types" tabindex="-1">Outcome types <a class="header-anchor" href="#outcome-types" aria-label="Permalink to &quot;Outcome types&quot;">​</a></h2><ul><li><code>success</code></li><li><code>failure</code></li><li><code>denied</code></li></ul><p>Failures include a non-null error category. Denials include authorization, validation, rate limiting, not found, conflict, and authentication cases.</p><h2 id="integrity" tabindex="-1">Integrity <a class="header-anchor" href="#integrity" aria-label="Permalink to &quot;Integrity&quot;">​</a></h2><ul><li><strong>Append-only by construction.</strong> A PostgreSQL trigger rejects <code>UPDATE</code> and <code>DELETE</code> on <code>audit_logs</code>, so no application path can rewrite or erase history.</li><li><strong>Fail closed.</strong> For mutating tools, the business write and the audit insert commit in the same transaction. If the audit record cannot be persisted, the change is rolled back and the tool returns an error.</li><li><strong>Redacted before storage.</strong> Values whose keys match patterns like password, secret, token, authorization, cookie, API key, private key, credential, hash, signature, or session are replaced with <code>[REDACTED]</code>. Payloads are capped at 4096 bytes, nested five levels deep, 20 array items, and 512 characters per string. Raw tool responses are not stored; array results are recorded as counts.</li></ul><h2 id="correlation-ids" tabindex="-1">Correlation IDs <a class="header-anchor" href="#correlation-ids" aria-label="Permalink to &quot;Correlation IDs&quot;">​</a></h2><p>A valid <code>X-Correlation-Id</code> request header is reused if it matches the expected shape; otherwise DockPilot generates one. The value is written to the audit event and echoed back on the response.</p><h2 id="admin-access" tabindex="-1">Admin access <a class="header-anchor" href="#admin-access" aria-label="Permalink to &quot;Admin access&quot;">​</a></h2><p>The audit log is available through:</p><ul><li><code>GET /api/v1/admin/audit-events</code></li><li><code>GET /api/v1/admin/audit-events/:id</code></li></ul><p>Both support server-side keyset pagination with a bounded page size. Filters include credential, tool, action, outcome, target, and a time range. Stored values stay redacted when an administrator opens an individual event.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Audit retention is manual. There is no automatic pruning or archival. Events accumulate until an operator handles them.</p>',19)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
